{
     "title": "CSCI-263: Honors Introduction to Computer Science Theory",
     "learningObjectives": [
       "Define and apply asymptotic notation to describe how resource usage scales with input size.",
       "Explain how loop invariants support formal proofs of algorithm correctness through initialization, maintenance, and termination.",
       "Identify and apply divide-and-conquer strategies to break complex problems into solvable subproblems."
     ],
     "beats": [
       {
         "title": "Foundations of Algorithm Analysis",
         "claim": "Algorithm analysis connects a precise problem specification to a correctness argument and resource bounds.",
         "example": "A sorting algorithm must guarantee that the output list contains all input elements in non-decreasing order.",
         "visualDirection": "Display a side-by-side comparison of a problem statement and its corresponding resource bounds, highlighting the connection between specification and analysis.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Asymptotic Notation Basics",
         "claim": "Asymptotic notation describes how resource use grows with input size.",
         "example": "Big-O notation captures the worst-case growth rate of an algorithm's time complexity as input size increases.",
         "visualDirection": "Show a graph plotting input size against resource usage, with asymptotic curves labeled to illustrate growth rates.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Loop Invariants for Correctness",
         "claim": "A loop invariant supports a proof by initialization, maintenance, and termination.",
         "example": "In a search loop, the invariant states that the target element, if present, must reside in the unexamined portion of the array.",
         "visualDirection": "Illustrate a loop structure with callouts marking the initialization step, the maintenance condition, and the termination check.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Divide-and-Conquer Strategy",
         "claim": "Divide-and-conquer algorithms split a problem, solve subproblems, and combine their results.",
         "example": "Merge sort divides an array into halves, recursively sorts each half, and merges the sorted halves into a single sorted array.",
         "visualDirection": "Animate a recursive tree structure where each node splits into two subproblems, then merges back up to show the combined result.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Recurrence Relations",
         "claim": "Recurrences describe the cost of recursive algorithms.",
         "example": "The recurrence T(n) = 2T(n/2) + O(n) describes the time complexity of merge sort by accounting for splitting and merging costs.",
         "visualDirection": "Display a recurrence equation alongside a step-by-step expansion showing how subproblem costs accumulate to the total cost.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Graph Algorithms Overview",
         "claim": "Graph algorithms operate on vertices and edges to answer reachability, ordering, connectivity, and path questions.",
         "example": "Breadth-first search traverses a graph level by level to find the shortest path in an unweighted graph.",
         "visualDirection": "Render a graph with vertices and edges, highlighting the traversal order and marking visited nodes to demonstrate reachability and pathfinding.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Dynamic Programming Fundamentals",
         "claim": "Dynamic programming records solutions to overlapping subproblems.",
         "example": "The Fibonacci sequence can be computed efficiently by storing previously calculated values to avoid redundant recursive calls.",
         "visualDirection": "Show a table filling process where each cell references previously computed values, emphasizing the reuse of subproblem solutions.",
         "sourceIds": ["mit-algorithms"]
       },
       {
         "title": "Core Methods and Data Structures",
         "claim": "Core methods include sorting, hashing, trees, graphs, shortest paths, and dynamic programming.",
         "example": "Hash tables map keys to locations using a collision strategy to enable fast key-value lookups.",
         "visualDirection": "Display a hash table with keys, hash functions, and collision resolution paths, illustrating how mappings are stored and retrieved.",
         "sourceIds": ["mit-algorithms", "opendsa"]
       },
       {
         "title": "Automata and Formal Languages",
         "claim": "Automata and formal languages describe machines, accepted strings, and computational limits.",
         "example": "A finite automaton accepts a string if its state transitions follow a defined sequence of symbols leading to an accepting state.",
         "visualDirection": "Illustrate a state diagram with transitions labeled by input symbols, showing which paths lead to an accepting state and which do not.",
         "sourceIds": ["opendsa"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "A disciplined solution states inputs and outputs, proves correctness, and then analyzes time and space.",
         "example": "Before implementing an algorithm, verify that the input/output contract is clear, the correctness proof holds, and the resource bounds are documented.",
         "visualDirection": "Present a checklist graphic with three boxes labeled 'Input/Output Contract', 'Correctness Proof', and 'Resource Bounds', each with a checkbox for verification.",
         "sourceIds": ["mit-algorithms"]
       }
     ]
   }
